Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='heldvalue', at=datetime(2026, 10, 22, 0, 0, 0), actor='assistant', title="A number the box recognises is a held value: a model reads a placeholder, and only the owner's tap reveals or sends it", body="An identity number, a verification code, a card, an account or routing number, an IBAN, a passport or A-number, and a file the box holds back are held values. The box keeps each where it already is, and a model, a log, a stored line, a request record and the public tree hold only its placeholder, which names its kind and a hint. The owner's trusted device reveals one on a tap, a send writes the value into the outgoing message only on the owner's tap, and a search row names only the kinds of value a message holds. The mail files and the index stay untouched, so the owner can still search by the number.", rationale='The owner needs the numbers that mail and documents carry, and they must still never reach a model.', supersedes=()))